/** Reference tables, the glossary and which upgrades cannot be undone. */
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    build
 * depends    scripts/game-wiki/render.mjs
 * used by    —
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
import { bullets, heading, sections, table, titleCase } from '../render.mjs'

export function build(context) {
  const { data, knowledge } = context.sdk

  // The same table can be filed under two keys; it gets one page.
  const tables = Object.values(data.REFERENCE_TABLES).filter(
    (reference, index, all) => all.findIndex(other => JSON.stringify(other) === JSON.stringify(reference)) === index,
  )
  for (const reference of tables) {
    context.page(
      `Reference: ${reference.title}`,
      sections(table(reference.header, reference.rows), `Back to ${context.link('Reference Tables')}.`),
      { source: 'REFERENCE_TABLES' },
    )
  }
  context.page(
    'Reference Tables',
    bullets(tables.map(reference => context.link(`Reference: ${reference.title}`, reference.title))),
    { source: 'REFERENCE_TABLES' },
  )

  // Terms about the SDK itself belong in its docs, not in a page about the game.
  const glossary = data.GLOSSARY.filter(entry => entry.domain !== 'sdk')
  const kinds = [...new Set(glossary.map(entry => entry.kind))]
  context.page(
    'Glossary',
    sections(
      ...kinds.map(kind =>
        sections(
          heading(2, `${titleCase(kind)}s`),
          table(
            ['Term', 'Area', 'Meaning'],
            glossary.filter(entry => entry.kind === kind).map(entry => [entry.term, titleCase(entry.domain), entry.definition]),
          ),
        ),
      ),
    ),
    { source: 'GLOSSARY' },
  )

  context.page(
    'Irreversible Upgrades',
    sections(
      heading(2, 'Cannot Be Undone'),
      bullets(knowledge.IRREVERSIBLE_UPGRADES),
      heading(2, 'Can Be Undone'),
      table(['Upgrade', 'How'], Object.entries(knowledge.REVERSIBLE_UPGRADES)),
    ),
    { source: ['IRREVERSIBLE_UPGRADES', 'REVERSIBLE_UPGRADES'], entry: '@beardedunicorn/thetowersdk/knowledge' },
  )

  context.group('Reference', ['Reference Tables', 'Glossary', 'Irreversible Upgrades'])
}
